#!/bin/sh
# Run as root on the Dokploy host. SERVICE_NAME must be the Docker Swarm
# service generated by Dokploy. Re-applies controls after each Dokploy update.
set -eu
: "${SERVICE_NAME:?Set SERVICE_NAME to the Dokploy Docker service name}"

harden() {
  service="$1"
  [ "$service" = "$SERVICE_NAME" ] || return 0
  spec=$(docker service inspect "$service" --format '{{.Spec.TaskTemplate.ContainerSpec.ReadOnly}} {{json .Spec.TaskTemplate.ContainerSpec.CapabilityDrop}}' 2>/dev/null || true)
  [ "$spec" = 'true ["ALL"]' ] && return 0
  docker service update --quiet --detach=true --force --read-only --cap-drop ALL "$service" >/dev/null
}

harden "$SERVICE_NAME"
docker events --filter type=service --filter event=create --filter event=update --format '{{.Actor.Attributes.name}}' |
while IFS= read -r service; do
  [ -n "$service" ] && harden "$service" || true
done
